async function requireOwnedPatch(db: Db, patchId: string, userId: string) {
  const rows = await db
    .select()
    .from(patches)
    .where(eq(patches.id, patchId))
    .for('update')
    .limit(1);
  const patch = rows[0];
  if (!patch) throw new NotFoundError('Patch not found');
  if (patch.userId !== userId) throw new ForbiddenError('Patch is not owned by this user');
  return patch;
}

